1	/** Strapi DTO types — mirror cms/src/api/country (see contracts/countries-api.md). */
2	export interface CountryIconDto {
3	  id: number;
4	  documentId: string;
5	  url: string;
6	  alternativeText: string | null;
7	}
8	
9	export interface CountryDto {
10	  id: number;
11	  documentId: string;
12	  name: string;
13	  code: string;
14	  icon: CountryIconDto | null;
15	}
16	
17	export interface CountriesResponseDto {
18	  data: CountryDto[];
19	  meta?: { pagination?: { page: number; pageSize: number; pageCount: number; total: number } };
20	}
21	
22	/** App model. `code` is lower case (e.g. 'co'). */
23	export interface Country {
24	  code: string;
25	  name: string;
26	  iconUrl: string | null;
27	  iconAlt: string;
28	}
29

1	import { Country, CountryDto } from './country.model';
2	
3	export function mapCountry(dto: CountryDto): Country {
4	  return {
5	    code: dto.code.toLowerCase(),
6	    name: dto.name,
7	    iconUrl: dto.icon?.url ?? null,
8	    iconAlt: dto.icon?.alternativeText || dto.name,
9	  };
10	}
11	
12	export function mapCountries(dtos: CountryDto[]): Country[] {
