7	describe('US-00 · FR-001 country mapper', () => {
8	  it('lower-cases the code', () => {
9	    expect(mapCountry(base).code).toBe('co');
10	  });
11	
12	  it('maps icon url and alternative text', () => {
13	    const country = mapCountry({
14	      ...base,
15	      icon: { id: 1, documentId: 'x', url: '/uploads/co.svg', alternativeText: 'Bandera de Colombia' },
16	    });
17	    expect(country.iconUrl).toBe('/uploads/co.svg');
18	    expect(country.iconAlt).toBe('Bandera de Colombia');
19	  });
20	
21	  it('returns null iconUrl and name as alt when there is no icon', () => {
22	    const country = mapCountry(base);
23	    expect(country.iconUrl).toBeNull();
24	    expect(country.iconAlt).toBe('Colombia');
25	  });
26	
27	  it('falls back to the name when alternativeText is null', () => {
28	    const country = mapCountry({
29	      ...base,
30	      icon: { id: 1, documentId: 'x', url: '/u.svg', alternativeText: null },
31	    });
32	    expect(country.iconAlt).toBe('Colombia');
33	  });
34	});
35	
36	describe('US-00 · FR-001 findByCode', () => {
37	  const countries = [mapCountry(base), mapCountry({ ...base, id: 2, name: 'Chile', code: 'CL' })];
38	
39	  it('finds case-insensitively', () => {
40	    expect(findCountryByCode(countries, 'CL')?.name).toBe('Chile');
41	    expect(findCountryByCode(countries, 'co')?.name).toBe('Colombia');
42	  });
