1	import { Injectable } from '@angular/core';
2	
3	export const QUOTE_SESSION_KEY = 'quote-session';
4	
5	export interface QuoteSession {
6	  countryCode: string;
7	  data: Record<string, unknown>;
8	}
9	
10	/** Single persistence helper for the quote wizard (sessionStorage). Never stores tokens. */
11	@Injectable({ providedIn: 'root' })
12	export class QuoteSessionStore {
13	  read(): QuoteSession | null {
14	    try {
15	      const raw = sessionStorage.getItem(QUOTE_SESSION_KEY);
16	      if (!raw) return null;
17	      const parsed: unknown = JSON.parse(raw);
18	      if (typeof parsed !== 'object' || parsed === null) return null;
19	      const { countryCode, data } = parsed as Partial<QuoteSession>;
20	      if (typeof countryCode !== 'string' || !countryCode) return null;
21	      const safeData =
22	        typeof data === 'object' && data !== null && !Array.isArray(data) ? data : {};
23	      return { countryCode, data: safeData };
24	    } catch {
25	      return null;
26	    }
27	  }
28	
29	  lastCountryCode(): string | null {
30	    return this.read()?.countryCode ?? null;
31	  }
32	
33	  hasData(): boolean {
34	    const session = this.read();
35	    return session !== null && Object.keys(session.data).length > 0;
36	  }
37	
38	  /** Same country keeps data; a different country resets it. */
39	  start(countryCode: string): void {
40	    const current = this.read();
41	    const data = current?.countryCode === countryCode ? current.data : {};
42	    this.write({ countryCode, data });
43	  }
44	
45	  /** Keeps the country, empties the form data. */
46	  discardData(): void {
47	    const current = this.read();
48	    if (current) this.write({ countryCode: current.countryCode, data: {} });
49	  }
50	
51	  clear(): void {
52	    try {
53	      sessionStorage.removeItem(QUOTE_SESSION_KEY);
54	    } catch {
55	      /* storage unavailable */
56	    }
57	  }
58	
59	  private write(session: QuoteSession): void {
60	    try {
61	      sessionStorage.setItem(QUOTE_SESSION_KEY, JSON.stringify(session));
62	    } catch {
63	      /* storage unavailable: degrade to no persistence */
64	    }
65	  }
66	}
67

1	import { QUOTE_SESSION_KEY, QuoteSessionStore } from './quote-session.store';
2	
3	function seed(value: unknown): void {
4	  sessionStorage.setItem(QUOTE_SESSION_KEY, JSON.stringify(value));
5	}
6	
7	describe('US-00 · FR-011 / FR-012 quote session store', () => {
8	  let store: QuoteSessionStore;
9	
10	  beforeEach(() => {
11	    sessionStorage.clear();
12	    store = new QuoteSessionStore();
13	  });
14	
15	  it('returns null when nothing is stored', () => {
16	    expect(store.read()).toBeNull();
17	    expect(store.lastCountryCode()).toBeNull();
18	    expect(store.hasData()).toBe(false);
19	  });
20	
21	  it('treats corrupt JSON as no session', () => {
22	    sessionStorage.setItem(QUOTE_SESSION_KEY, '{not json');
23	    expect(store.read()).toBeNull();
24	    expect(store.hasData()).toBe(false);
25	  });
26	
27	  it('treats a malformed shape as no session', () => {
28	    seed({ data: {} });
29	    expect(store.read()).toBeNull();
30	  });
31	
32	  it('start creates a session with empty data', () => {
33	    store.start('co');
34	    expect(store.read()).toEqual({ countryCode: 'co', data: {} });
35	    expect(store.lastCountryCode()).toBe('co');
36	  });
37	
38	  it('hasData is true only when data has at least one key', () => {
39	    seed({ countryCode: 'co', data: {} });
40	    expect(store.hasData()).toBe(false);
41	    seed({ countryCode: 'co', data: { plate: 'ABC123' } });
42	    expect(store.hasData()).toBe(true);
43	  });
44	
45	  it('start with the same country keeps the data (FR-011)', () => {
46	    seed({ countryCode: 'co', data: { plate: 'ABC123' } });
47	    store.start('co');
48	    expect(store.read()?.data).toEqual({ plate: 'ABC123' });
49	  });
50	
51	  it('start with a different country resets the data (FR-012)', () => {
52	    seed({ countryCode: 'co', data: { plate: 'ABC123' } });
53	    store.start('cl');
54	    expect(store.read()).toEqual({ countryCode: 'cl', data: {} });
55	  });
56	
57	  it('discardData keeps the country and empties data', () => {
58	    seed({ countryCode: 'co', data: { plate: 'ABC123' } });
59	    store.discardData();
60	    expect(store.read()).toEqual({ countryCode: 'co', data: {} });
61	  });
62	
63	  it('clear removes the session', () => {
64	    seed({ countryCode: 'co', data: { a: 1 } });
65	    store.clear();
66	    expect(store.read()).toBeNull();
67	  });
68	});
69

