import type { FieldRules, FieldType } from '../validation/validation.model';

/** Strapi DTOs — mirror cms/src/api/form-field (see contracts/form-fields-api.md). */
export interface FormValidatorDto {
  id: number;
  name: string;
  value: number | null;
}

export interface FormValidationsDto {
  id: number;
  min: number | null;
  max: number | null;
  pattern: string | null;
  validators: FormValidatorDto[] | null;
}

export interface FormOptionDto {
  id: number;
  label: string;
  value: string;
}

export interface FormFieldDto {
  id: number;
  documentId: string;
  key: string;
  label: string;
  type: string;
  required: boolean;
  helpText: string | null;
  placeholder: string | null;
  errorMessage: string;
  order: number;
  section: string;
  validations: FormValidationsDto | null;
  options: FormOptionDto[] | null;
}

export interface FormFieldsResponseDto {
  data: FormFieldDto[];
  meta?: { pagination?: { page: number; pageSize: number; pageCount: number; total: number } };
}

/** App models. */
export type FormSection = 'policyholder' | 'vehicle';

export interface FieldOption {
  label: string;
  value: string;
}

export interface FormFieldDescriptor {
  key: string;
  label: string;
  type: FieldType;
  required: boolean;
  helpText: string | null;
  placeholder: string | null;
  errorMessage: string;
  order: number;
  section: FormSection;
  options: FieldOption[];
  rules: FieldRules;
}

export interface FormSections {
  policyholder: FormFieldDescriptor[];
  vehicle: FormFieldDescriptor[];
}

import type { FieldType } from '../validation/validation.model';
import type {
  FormFieldDescriptor,
  FormFieldDto,
  FormSection,
  FormSections,
} from './form-field.model';

const FIELD_TYPES: readonly FieldType[] = ['text', 'number', 'select', 'date', 'checkbox'];
const SECTIONS: readonly FormSection[] = ['policyholder', 'vehicle'];

function isFieldType(value: string): value is FieldType {
  return (FIELD_TYPES as readonly string[]).includes(value);
}

function isSection(value: string): value is FormSection {
  return (SECTIONS as readonly string[]).includes(value);
}

function mapField(dto: FormFieldDto, section: FormSection, type: FieldType): FormFieldDescriptor {
  return {
    key: dto.key,
    label: dto.label,
    type,
    required: dto.required,
    helpText: dto.helpText ?? null,
    placeholder: dto.placeholder ?? null,
    errorMessage: dto.errorMessage,
    order: dto.order,
    section,
    options: (dto.options ?? []).map((o) => ({ label: o.label, value: o.value })),
    rules: {
      type,
      required: dto.required,
      min: dto.validations?.min ?? null,
      max: dto.validations?.max ?? null,
      pattern: dto.validations?.pattern ?? null,
      validators: (dto.validations?.validators ?? []).map((v) => ({
        name: v.name,
        value: v.value ?? null,
      })),
    },
  };
}

/** Groups CMS fields by section, sorted by `order` (stable). Unknown types/sections are dropped. */
export function mapFormFields(dtos: FormFieldDto[]): FormSections {
  const result: FormSections = { policyholder: [], vehicle: [] };
  for (const dto of dtos) {
    if (!isSection(dto.section)) {
      console.warn(`Form field "${dto.key}" dropped: unknown section "${dto.section}".`);
      continue;
    }
    if (!isFieldType(dto.type)) {
      console.warn(`Form field "${dto.key}" dropped: unknown type "${dto.type}".`);
      continue;
    }
    result[dto.section].push(mapField(dto, dto.section, dto.type));
  }
  // Array.prototype.sort is stable: equal orders keep CMS order.
  result.policyholder.sort((a, b) => a.order - b.order);
  result.vehicle.sort((a, b) => a.order - b.order);
  return result;
}

import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable, map } from 'rxjs';
import { mapFormFields } from './form-field.mapper';
import { FormFieldsResponseDto, FormSections } from './form-field.model';

@Injectable({ providedIn: 'root' })
export class FormFieldService {
  private readonly http = inject(HttpClient);

  load(countryCode: string): Observable<FormSections> {
    const params = new HttpParams()
      .set('filters[country][code][$eq]', countryCode.toUpperCase())
      .set('sort[0]', 'section:asc')
      .set('sort[1]', 'order:asc')
      .set('populate[validations][populate][validators]', 'true')
      .set('populate[options]', 'true')
      .set('pagination[pageSize]', '100');
    return this.http
      .get<FormFieldsResponseDto>('/api/form-fields', { params })
      .pipe(map((response) => mapFormFields(response.data)));
  }
}

import { mapFormFields } from './form-field.mapper';
import { FormFieldDto } from './form-field.model';

function dto(overrides: Partial<FormFieldDto>): FormFieldDto {
  return {
    id: 1,
    documentId: 'd',
    key: 'k',
    label: 'Label',
    type: 'text',
    required: true,
    helpText: null,
    placeholder: null,
    errorMessage: 'Error',
    order: 1,
    section: 'policyholder',
    validations: null,
    options: null,
    ...overrides,
  };
}

describe('US-01 · FR-002 form field mapper grouping and order', () => {
  it('groups by section and sorts by order', () => {
    const result = mapFormFields([
      dto({ key: 'b', order: 2, section: 'vehicle' }),
      dto({ key: 'c', order: 2 }),
      dto({ key: 'a', order: 1 }),
      dto({ key: 'd', order: 1, section: 'vehicle' }),
    ]);
    expect(result.policyholder.map((f) => f.key)).toEqual(['a', 'c']);
    expect(result.vehicle.map((f) => f.key)).toEqual(['d', 'b']);
  });

  it('keeps CMS order for equal order values (stable)', () => {
    const result = mapFormFields([dto({ key: 'x', order: 1 }), dto({ key: 'y', order: 1 })]);
    expect(result.policyholder.map((f) => f.key)).toEqual(['x', 'y']);
  });

  it('returns empty sections for no data', () => {
    expect(mapFormFields([])).toEqual({ policyholder: [], vehicle: [] });
  });

  it('drops unknown types and sections with a warning', () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => undefined);
    const result = mapFormFields([
      dto({ key: 'ok' }),
      dto({ key: 'bad-type', type: 'slider' }),
      dto({ key: 'bad-section', section: 'payment' }),
    ]);
    expect(result.policyholder.map((f) => f.key)).toEqual(['ok']);
    expect(result.vehicle).toEqual([]);
    expect(warn).toHaveBeenCalledTimes(2);
    warn.mockRestore();
  });
});

describe('US-01 · FR-003 form field mapper rules and options', () => {
  it('maps null validations to empty rules mirroring required', () => {
    const [field] = mapFormFields([dto({ required: false, type: 'number' })]).policyholder;
    expect(field.rules).toEqual({
      type: 'number',
      required: false,
      min: null,
      max: null,
      pattern: null,
      validators: [],
    });
  });

  it('maps min, max, pattern and named validators', () => {
    const [field] = mapFormFields([
      dto({
        type: 'date',
        validations: {
          id: 1,
          min: 1,
          max: 9,
          pattern: '^[A-Z]+$',
          validators: [{ id: 1, name: 'legalAge', value: null }],
        },
      }),
    ]).policyholder;
    expect(field.rules).toEqual({
      type: 'date',
      required: true,
      min: 1,
      max: 9,
      pattern: '^[A-Z]+$',
      validators: [{ name: 'legalAge', value: null }],
    });
  });

  it('maps options, and null options to an empty list', () => {
    const [select] = mapFormFields([
      dto({ type: 'select', options: [{ id: 1, label: 'Chevrolet', value: 'chevrolet' }] }),
    ]).policyholder;
    expect(select.options).toEqual([{ label: 'Chevrolet', value: 'chevrolet' }]);
    const [text] = mapFormFields([dto({ options: null })]).policyholder;
    expect(text.options).toEqual([]);
  });
});

